.shared-board-tabs{display:flex;justify-content:center;gap:var(--size-space-4_0,4px);flex-wrap:wrap;}.shared-board-tabs button{min-height:var(--size-length-36_0,36px);padding:var(--size-space-5_0,4px) var(--size-space-12_0,12px);border:var(--size-border-1_0,1px) solid var(--color-border-subtle,#b6c8b5);border-radius:var(--size-radius-10_0,8px);background:var(--color-surface-raised,#e6e9dc);color:var(--color-text-primary,var(--color-material-card-back-face,#31594c));font:700 var(--size-type-12_0,12px) system-ui;}.shared-board-tabs button[aria-pressed=true]{background:var(--color-action-primary,var(--color-material-card-back-face,#31594c));color:var(--color-action-on-primary,#fff9e8);}
