/* The app draws the interaction outline; use the opposing piece colour. */
.checker-piece{--ui-action-outline:#294f38;}
.checker-piece.owner-1{--ui-action-outline:#ffdc93;}

/* Selection and valid drop cues retain the board fill and use a thin frame. */
.checkers-scene :is(.checker-cell,.checker-piece){--interaction-ring-width:2px;}
.checkers-scene .checker-cell.playroom-drop-hover{outline-width:var(--size-border-2_0,2px)!important;outline-offset:-2px;background-color:var(--color-material-board-dark,#84a286)!important;box-shadow:none!important;}
